package com.supportsphere.model; import java.time.*; import java.util.*; public class Volunteer extends User { private int experienceYears,ratingCount; private LocalTime availabilityStart,availabilityEnd; private double rating; private String verificationStatus,rejectionReason; private final Set<String> skills=new HashSet<>(); public Volunteer(int id,String n,String e,String p,String a,String c,String l){super(id,n,e,p,Role.VOLUNTEER,a,c,l);} public String getDashboardType(){return "Volunteer Dashboard";} public int getExperienceYears(){return experienceYears;} public void setExperienceYears(int v){experienceYears=v;} public LocalTime getAvailabilityStart(){return availabilityStart;} public void setAvailabilityStart(LocalTime v){availabilityStart=v;} public LocalTime getAvailabilityEnd(){return availabilityEnd;} public void setAvailabilityEnd(LocalTime v){availabilityEnd=v;} public double getRating(){return rating;} public void setRating(double v){rating=v;} public int getRatingCount(){return ratingCount;} public void setRatingCount(int v){ratingCount=v;} public String getVerificationStatus(){return verificationStatus;} public void setVerificationStatus(String v){verificationStatus=v;} public String getRejectionReason(){return rejectionReason;} public void setRejectionReason(String v){rejectionReason=v;} public Set<String> getSkills(){return skills;} }
